export const projects = [
  {slug:'aracore',index:'01',name:'Aracore',year:'2026',kind:'Produit numérique',headline:'Voir la disponibilité d’une laverie étudiante avant de se déplacer.',intro:'Une application pensée pour les résidences étudiantes : disponibilité communautaire, cycles, entraide locale et bons plans.',url:'https://aracore.fr',accent:'#FFE100',dark:'#06131D',stack:['Flutter','Dart','PWA','Supabase','Firebase'],roles:['Produit','UX / UI','Développement','Déploiement'],challenge:'Éviter un geste très banal : descendre à la laverie pour découvrir qu’aucune machine n’est disponible.',approach:'Aracore repose sur des signalements simples, des états lisibles et une logique de cycle pensée pour fonctionner sans ajouter de matériel dans la résidence.',detail:'Le projet réunit conception produit, interface mobile, logique temps réel, authentification, règles d’accès, notifications et déploiement PWA.'},
  {slug:'aracnet',index:'02',name:'aracnet',year:'2026',kind:'Projet éditorial',headline:'Explorer une façon plus directe de présenter l’information sur le web.',intro:'Un projet éditorial qui travaille la hiérarchie, la lisibilité et une identité web plus nette.',url:'https://aracnet.fr',accent:'#FFE100',dark:'#10120A',stack:['React','JavaScript','Responsive Web','Editorial UI'],roles:['Direction','Identité','Web','Éditorial'],challenge:'Construire une interface éditoriale qui ne dépende ni d’un template de presse classique ni d’une imitation de réseau social.',approach:'Le travail porte surtout sur la hiérarchie, le rythme, la navigation et la manière dont différents formats de contenu peuvent cohabiter.',detail:'aracnet sert de terrain pour le design éditorial, la recherche d’information, la performance front et la cohérence d’une interface riche en contenu.'},
  {slug:'craph',index:'03',name:'CRAPH.fr',year:'2026',kind:'Site institutionnel',headline:'Présenter clairement les services d’un centre de rééducation et d’appareillage.',intro:'Site du Centre de Rééducation et d’Appareillage Prothétique et Orthétique de Libreville.',url:'https://craph.fr',accent:'#FFE100',dark:'#13100A',image:'/images/craph_img.jpg',stack:['Web','UX','Contenu','Responsive','SEO'],roles:['Conception','UX','Intégration','Mise en ligne'],challenge:'Rendre des activités médicales et techniques faciles à comprendre sans surcharger le visiteur.',approach:'L’architecture privilégie les services, les informations utiles et les moyens de contact, avec une interface volontairement sobre.',detail:'CRAPH.fr a demandé de travailler la structure du contenu, le responsive, le référencement de base et une identité adaptée à un contexte institutionnel.'}
